WITH italian2017_race AS (
    SELECT raceId FROM races WHERE year = 2017 AND name = 'Italian Grand Prix'
), q3_non_null AS (
    SELECT driverId, Q3 FROM qualifying WHERE raceId = (SELECT raceId FROM italian2017_race) AND Q3 IS NOT NULL
),
fastest_q3_time AS (
    SELECT MIN(Q3) AS fastest_time FROM q3_non_null
)
SELECT d.code AS driver_code, q3.Q3 AS fastest_q3_time
FROM q3_non_null q3
JOIN fastest_q3_time fq ON fq.fastest_time = q3.Q3
JOIN drivers d ON d.driverId = q3.driverId;

